let resumeReport=null,resumeMode=workspaceSession.getItem('proof-selected-listing')?'job':'general';
function resumePage(){const hasResume=Boolean(marketplaceResume().trim());return title('Make your experience stand out.','Review your resume or see how it fits a specific opportunity.')+`<div class="resume-workspace"><section class="panel resume-input"><div class="editor-heading"><div><span class="section-label">RESUME STUDIO</span><h2>Build a stronger application</h2></div></div><div class="review-type-switch" role="group" aria-label="Review type"><button class="${resumeMode==='general'?'active':''}" onclick="setResumeMode('general')">${icon('resume',17)} Resume review</button><button class="${resumeMode==='job'?'active':''}" onclick="setResumeMode('job')">${icon('briefcase',17)} Match a job</button></div>${savedResumeHTML()}<form id="resume-review-form"><label class="upload-zone ${hasResume?'compact-upload':''}" id="resume-drop"><span>${icon('resume',25)}</span><div><b>${hasResume?'Upload a different resume':'Add your resume'}</b><small>Drag a file here or choose a file · PDF, DOCX, TXT</small></div><input id="resume-file" type="file" accept=".pdf,.docx,.txt,text/plain,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></label><p id="file-status" class="resume-hint" role="status">Up to 5 MB. Saved privately to your account.</p><div id="resume-upload-progress" hidden></div><label class="field">Resume text<textarea id="review-resume" required minlength="100" maxlength="30000" placeholder="Upload a file or paste your resume here.">${esc(workspaceSession.getItem('proof-resume')||'')}</textarea></label><div class="resume-counter" id="resume-count"></div><div id="job-fields" ${resumeMode==='job'?'':'hidden'}><label class="field">Choose an opportunity<select id="review-listing" onchange="selectResumeListing(this.value)"><option value="">Paste a job description</option>${jobs.map(j=>`<option value="${j.id}" ${workspaceSession.getItem('proof-selected-listing')===String(j.id)?'selected':''}>${esc(j.c)} · ${esc(j.title)}</option>`).join('')}</select></label><div id="selected-listing-summary">${listingSummary()}</div><label class="field">Job title<input id="review-job-title" maxlength="150" placeholder="e.g. Frontend developer" value="${esc(workspaceSession.getItem('proof-job-title')||'')}"></label><label class="field">Job description<textarea id="review-job" minlength="80" maxlength="20000" placeholder="Include the responsibilities and requirements…">${esc(workspaceSession.getItem('proof-job')||'')}</textarea></label></div><div class="review-method-row"><label class="field">Review method<select id="review-method"><option value="local">Instant text review</option><option value="ai">AI review · free tier</option></select></label><p id="backend-status" class="resume-hint" role="status">Checking AI availability…</p></div><div id="ai-settings" hidden><p class="resume-hint">AI review sends your resume to Google Gemini. Free-tier content may be used to improve its products.</p></div><div class="resume-actions"><button class="primary" id="run-review">Review my resume ${icon('arrow',16)}</button><button class="text-control" type="button" onclick="loadResumeExample()">Try an example</button></div><p id="review-error" class="review-error" role="alert"></p></form><div class="review-privacy-note">${icon('lock',14)} Your resume is saved in your account. <button class="text-control" onclick="clearResume()">Clear resume</button></div></section><section id="resume-results" aria-live="polite">${resumeReport?reportHTML(resumeReport):`<div class="review-empty-state"><div class="review-document-art" aria-hidden="true"><span>${icon('resume',39)}</span><div></div><div></div><div></div><b>${icon('check',16)} Ready for a fresh perspective</b></div><span class="section-label">A CLEARER NEXT STEP</span><h2>Good experience deserves<br>a clear story.</h2><p>Get focused feedback on what’s working and what to improve.</p><ul><li>${icon('check',16)} Clearer accomplishments and impact</li><li>${icon('check',16)} Evidence for the skills a role needs</li><li>${icon('check',16)} Practical edits you can make next</li></ul><small>Feedback is coaching, not a hiring prediction.</small></div>`}</section></div>`}

function setResumeMode(mode){saveResumeDraft();resumeReport=null;resumeMode=mode;render()}
function bindResume(){$('#review-resume').value=workspaceSession.getItem('proof-resume')||'';$('#review-job').value=workspaceSession.getItem('proof-job')||'';$('#review-job-title').value=workspaceSession.getItem('proof-job-title')||'';const selected=getResumeListing();if(selected){$('#review-job').value=listingDescription(selected);$('#review-job-title').value=selected.title;}$('#review-listing').disabled=resumeMode!=='job';$('#review-job').readOnly=Boolean(selected);$('#review-job-title').readOnly=Boolean(selected);$('#review-job').disabled=resumeMode!=='job';$('#review-job-title').disabled=resumeMode!=='job';const text=$('#review-resume');const count=()=>{setMarketplaceResume(text.value);$('#resume-count').textContent=`${text.value.trim()?text.value.trim().split(/\s+/).length:0} words · ${text.value.length.toLocaleString()}/30,000 characters`};count();text.oninput=count;$('#resume-file').onchange=e=>readResumeFile(e.target.files[0]);const drop=$('#resume-drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');readResumeFile(e.dataTransfer.files[0])};$('#review-method').onchange=e=>{$('#ai-settings').hidden=e.target.value!=='ai'};$('#resume-review-form').onsubmit=runResumeReview;checkResumeBackend()}
async function parseResumeFile(file){if(file.size>5*1024*1024)throw Error('File is too large. Choose a file under 5 MB.');let text,ext=file.name.split('.').pop().toLowerCase();if(ext==='txt')text=await file.text();else if(ext==='pdf'){const pdf=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');pdf.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';const doc=await pdf.getDocument({data:await file.arrayBuffer(),isEvalSupported:false}).promise;if(doc.numPages>20)throw Error('Use a resume with 20 pages or fewer.');let pages=[];for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i),content=await page.getTextContent();pages.push(content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join(''))}text=pages.join('\n');await doc.destroy()}else if(ext==='docx'){if(!window.mammoth)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.9.0/mammoth.browser.min.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s)});text=(await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()})).value}else throw Error('Choose a PDF, DOCX, or TXT file.');if(!text||text.trim().length<50)throw Error('Not enough text could be extracted. Scanned PDFs need OCR; paste your resume text instead.');if(text.length>30000)throw Error('This file exceeds 30,000 characters. Paste a shorter version.');return text}
async function readResumeFile(file){
if(!file)return;
if(typeof requireAccount==='function'&&!requireAccount())return;
const owner=Account.user.id,epoch=Account.sessionEpoch,status=$('#file-status');
const current=()=>Account.user?.id===owner&&Account.sessionEpoch===epoch;
const inputs=document.querySelectorAll('#resume-file,#profile-resume-file');
inputs.forEach(input=>input.disabled=true);
status.textContent='Processing and saving your resume…';if(typeof showBusyAt==='function')showBusyAt('resume-upload-progress','Reading your file','Extracting your resume text.');
try{

const text=await parseResumeFile(file);
if(!current())return;
if(text.trim().length<100)throw Error('Add at least 100 characters of resume text.');
const report=ResumeEngine.review(text);
const ext=file.name.split('.').pop().toLowerCase();
const path=owner+'/'+crypto.randomUUID()+'.'+ext;
const mime={pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',txt:'text/plain'}[ext];
if(typeof showBusyAt==='function')showBusyAt('resume-upload-progress','Saving your resume','Uploading your file to your private account.');
const uploaded=await Account.client.storage.from('account-resumes').upload(path,file,{contentType:mime,upsert:false});
if(uploaded.error)throw Error('Could not store your resume. Please try again.');
if(!current()){await Account.client.storage.from('account-resumes').remove([path]);return;}
const previous=savedResumeFile();
workspaceLocal.setItem('proof-resume-file',JSON.stringify({path,name:file.name,size:file.size,uploadedAt:new Date().toISOString()}));
setMarketplaceResume(text);
workspaceLocal.setItem('proof-resume-report',JSON.stringify(report));

resumeReport=report;
await saveWorkspace();
if(!current())return;
if(previous?.path)await Account.client.storage.from('account-resumes').remove([previous.path]);
render();
const message=$('#file-status');if(message)message.textContent='Resume saved. Prepare AI profile suggestions below, then choose which changes to save.';
}catch(e){if(current()){const message=$('#file-status');if(message)message.textContent=e.message||'Could not process your resume. Please try again.';}}
finally{inputs.forEach(input=>input.disabled=false);if(typeof clearBusyAt==='function')clearBusyAt('resume-upload-progress');}
}
function savedResumeFile(){try{return JSON.parse(workspaceLocal.getItem('proof-resume-file')||'null')}catch{return null}}
function savedResumeHTML(manage=false){const file=savedResumeFile(),hasText=Boolean((workspaceSession.getItem('proof-resume')||'').trim());if(!file&&!hasText)return '';return `<div class="notice"><b>${file?'Saved resume: '+esc(file.name):'Saved resume text'}</b><p>${file?Math.ceil(file.size/1024)+' KB · ':''}Used across your account</p><div class="resume-actions">${file?'<button type="button" class="outline" onclick="downloadSavedResume()">Download resume</button>':''}${manage?'<button type="button" class="outline" onclick="clearProfileResume()">Clear resume</button><button type="button" class="primary" onclick="chooseProfileResume()">Upload a new resume</button>':'<a class="outline" href="#profile">Manage resume in profile</a>'}</div></div>`;}
async function clearProfileResume(){saveProfileDraft();try{await clearResume()}catch{toast('Could not clear your resume. Please try again.')}}

async function downloadSavedResume(){const file=savedResumeFile();if(!file)return;const owner=Account.user?.id;try{const result=await Account.client.storage.from('account-resumes').download(file.path);if(Account.user?.id!==owner)return;if(result.error)throw result.error;const url=URL.createObjectURL(result.data),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{toast('Could not download your resume. Please try again.')}}

function loadResumeExample(){workspaceSession.removeItem('proof-selected-listing');$('#review-listing').value='';$('#review-job').readOnly=false;$('#review-job-title').readOnly=false;$('#selected-listing-summary').innerHTML='';$('#review-resume').value=`Alex Johnson\nalex@example.com | https://github.com/example\nEDUCATION\nBS Computer Science, 2026\nSKILLS\nJavaScript, React, HTML, CSS, Git, SQL\nPROJECTS\n- Built a React dashboard for 40 student volunteers to coordinate weekly community events.\n- Developed accessible forms and reduced incomplete submissions by 20% in a class usability study.\n- Worked on a customer analytics report using SQL.\nEXPERIENCE\n- Collaborated with a team of 4 students to launch a campus resource directory.\n- Presented research findings to a student advisory group.\n`;$('#review-job').value='Junior Frontend Developer\nRequired: React, JavaScript, TypeScript, HTML, CSS, Git, Testing, and Accessibility.\nBuild responsive interfaces, collaborate with designers, write unit tests, and communicate technical decisions.\nA degree in a relevant field or equivalent practical experience is welcome.';$('#review-job-title').value='Junior Frontend Developer';$('#review-resume').oninput();toast('Example loaded. Choose a review type, then run your review.')}
async function clearResume(){const file=savedResumeFile();if(file){const result=await Account.client.storage.from('account-resumes').remove([file.path]);if(result.error){toast('Could not delete your saved resume. Please try again.');return}}workspaceLocal.removeItem('proof-resume-file');workspaceLocal.removeItem('proof-resume-report');['proof-resume','proof-job','proof-job-title','proof-selected-listing'].forEach(k=>workspaceSession.removeItem(k));workspaceLocal.removeItem('proof-ai-endpoint');workspaceLocal.removeItem('lp-resume');if(typeof detected!=='undefined')detected=[];resumeReport=null;await saveWorkspace();render();toast('Resume cleared across your account')}
async function runResumeReview(e){e.preventDefault();if(typeof Account!=='undefined'&&!Account.user){location.hash='login';return}const resume=$('#review-resume').value.trim(),job=resumeMode==='job'?$('#review-job').value.trim():'',jobTitle=resumeMode==='job'?$('#review-job-title').value.trim():'';const error=$('#review-error');error.textContent='';if(resume.length<100){error.textContent='Add at least 100 characters of resume text.';return}if(resumeMode==='job'&&job.length<80){error.textContent='Add at least 80 characters from the job description.';return}const ai=$('#review-method').value==='ai';const button=$('#run-review');button.disabled=true;button.textContent=ai?'Reading your experience…':'Reviewing your resume…';$('#resume-results').innerHTML=loadingView('Reviewing your resume',ai?'Reading your experience and the role requirements.':'Checking structure, clarity, and evidence.',false,['Read your resume','Review the evidence','Prepare feedback'],0);try{workspaceSession.setItem('proof-resume',resume);workspaceSession.setItem('proof-job',job);workspaceSession.setItem('proof-job-title',jobTitle);if(ai){const base=resumeAPIBase();const session=(await Account.client.auth.getSession()).data.session;if(!session)throw Error('Your session has expired. Sign in again.');const response=await fetch(base+'/api/resume',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({resume,job:jobTitle?jobTitle+'\n'+job:job,listingId:resumeMode==='job'?getResumeListing()?.id:null,field:getResumeListing()?.cat||graduateProfile().field||'Development'}),signal:AbortSignal.timeout(55000)});let report;try{report=await response.json()}catch{throw Error('This server did not return a review. Check that the Nextwork AI endpoint is deployed.')}if(!response.ok)throw Error(report.error||'AI review could not be completed.');if(!Array.isArray(report.metrics)||!Array.isArray(report.improvements))throw Error('The server returned an invalid review.');resumeReport=report}else resumeReport=ResumeEngine.review(resume,jobTitle?jobTitle+'\n'+job:job);resumeReport.listingId=resumeMode==='job'?getResumeListing()?.id:null;if(resumeReport.source==='local'&&resumeReport.listingId){const fit=ResumeEngine.compatibility(resume,getResumeListing());resumeReport.match.score=fit.score;resumeReport.match.matched=fit.matched;resumeReport.match.missing=fit.missing;resumeReport.match.jobScore=fit.jobScore;resumeReport.match.fieldScore=fit.fieldScore;resumeReport.match.field=fit.field;resumeReport.match.requirements=fit.requirements;resumeReport.match.summary='Weighted evidence check: 75% listing criteria and 25% field foundations. Missing evidence does not mean you lack the skill.';}workspaceLocal.setItem('proof-resume-report',JSON.stringify(resumeReport));$('#resume-results').innerHTML=loadingView('Preparing your feedback','Saving the review to your account.',false,['Read your resume','Review the evidence','Prepare feedback'],2);await saveWorkspace();$('#resume-results').innerHTML=reportHTML(resumeReport);$('#resume-results').scrollIntoView({behavior:'smooth',block:'start'})}catch(err){error.textContent=err.message||'Review failed. Please try again.';$('#resume-results').innerHTML='<div class="review-error-card"><h2>Your review couldn’t finish.</h2><p>'+esc(error.textContent)+'</p><p>Check the details on the left and try again.</p></div>'}finally{button.disabled=false;button.textContent='Review my resume ↗'}}
let resumeReportTab='summary';
function setResumeReportTab(tab){resumeReportTab=tab;if(resumeReport)$('#resume-results').innerHTML=reportHTML(resumeReport)}
function reportHTML(r){const score=n=>Number.isFinite(+n)?Math.max(0,Math.min(100,Math.round(+n))):0;const list=x=>Array.isArray(x)?x:[];return `<div class="review-report-heading"><span class="section-label">YOUR RESULTS</span><h2>A clearer picture of your experience.</h2><div class="report-view-tabs" role="tablist">${[['summary','Summary'],...(r.match?[['match','Job fit']]:[]),['improve','Next steps']].map(([tab,label])=>`<button role="tab" aria-selected="${resumeReportTab===tab}" onclick="setResumeReportTab('${tab}')">${label}</button>`).join('')}</div></div>${r.fallbackReason?`<div class="notice">${esc(r.fallbackReason)}</div>`:''}<div class="panel wide-panel report-card" ${resumeReportTab==='summary'?'':'hidden'}><div class="section-title"><div class="eyebrow">YOUR RESUME REVIEW</div><span class="tag">${r.source==='ai'?'Free-tier AI review':'Free text checks'}</span></div><div class="report-score-row"><div class="score-ring" style="--score:${score(r.score)}"><strong>${score(r.score)}</strong><small>/ 100</small></div><div><h2>${score(r.score)>=75?'A strong foundation. Keep refining.':'Let’s make your experience clearer.'}</h2><p>${esc(r.summary||'')}</p></div></div><p class="resume-hint">${r.source==='ai'?'AI coaching estimate':'Text-check health score'} · Not an employer ATS score or proof of qualification.</p><div class="score-metrics">${list(r.metrics).map(m=>`<div><div class="progress-label"><b>${esc(m.name)}</b><strong>${score(m.score)}</strong></div><div class="progress"><i style="width:${score(m.score)}%"></i></div><p>${esc(m.detail)}</p></div>`).join('')}</div>${list(r.strengths).length?`<h3>What’s working</h3>${list(r.strengths).map(s=>`<p class="strength-line">✓ &nbsp; ${esc(s)}</p>`).join('')}`:''}</div>${r.match?`<div class="panel wide-panel report-card" ${resumeReportTab==='match'?'':'hidden'}><div class="eyebrow">JOB DESCRIPTION ALIGNMENT</div>${r.listingId?listingSummary(r.listingId,true):''}<h2>${r.match.score===null?'Manual review needed':score(r.match.score)+'% resume compatibility'}</h2><p>${esc(r.match.summary)}</p>${r.match.jobScore!=null?`<div class="match-scorecards"><div><strong>${score(r.match.jobScore)}%</strong><span>Listing criteria · 75% weight</span></div><div><strong>${score(r.match.fieldScore)}%</strong><span>${esc(r.match.field||'Field')} foundations · 25% weight</span></div></div>`:''}<h3>Evidence found</h3><div class="tags">${list(r.match.matched).map(s=>`<span class="tag tag-positive">✓ ${esc(s)}</span>`).join('')||'<span class="resume-hint">No matching skill terms identified.</span>'}</div><h3 style="margin-top:20px">Not evidenced in this resume</h3><div class="tags">${list(r.match.missing).map(s=>`<span class="tag tag-gap">${esc(s)}</span>`).join('')||'<span class="resume-hint">No recognized missing skill terms. Review all requirements below.</span>'}</div><p class="resume-hint">Missing resume evidence does not mean you lack the skill. Add it only if it reflects your actual experience.</p>${list(r.match.requirements).map(x=>`<div class="requirement"><b>${esc(x.text)}</b><span class="tag">${esc(x.status)}${x.kind?' · '+esc(x.kind):''}</span><p>${esc(x.evidence)}</p>${x.reason?`<p>${esc(x.reason)}</p>`:''}</div>`).join('')}</div>`:''}<div class="panel wide-panel report-card" ${resumeReportTab==='improve'?'':'hidden'}><div class="section-title"><h2>Your improvement plan</h2><button class="outline" style="width:auto" onclick="downloadResumeReport()">↓ Download report</button></div>${list(r.improvements).map((x,i)=>`<div class="roadmap-item"><span class="step">${i+1}</span><div><span class="tag">${esc(x.priority)} priority</span><h3 style="margin-top:9px">${esc(x.title)}</h3><p>${esc(x.detail)}</p></div></div>`).join('')||'<p>No major issues detected by these checks. Have a trusted reviewer check accuracy and relevance.</p>'}${list(r.rewrites).length?`<h3 style="margin-top:25px">Make each line more specific</h3>${list(r.rewrites).map(x=>`<div class="rewrite"><small>ORIGINAL</small><p>${esc(x.before)}</p><small>EDITING DIRECTION</small><p><b>${esc(x.after)}</b></p><p class="resume-hint">${esc(x.note)}</p></div>`).join('')}`:''}<div class="notice">Need stronger evidence? Complete a real project, document your contribution, and add the outcome to your resume. <a href="#explore" class="text-link">Find your next project ↗</a></div><button class="outline" onclick="document.querySelector('#review-resume').focus();document.querySelector('#review-resume').scrollIntoView({behavior:'smooth'})">Edit your resume & review again ↑</button></div>`}
function downloadResumeReport(){if(!resumeReport)return;const r=resumeReport,text=['PROOFLANE RESUME REVIEW',r.source==='ai'?'Free-tier AI review':'Free text checks',`Health score: ${r.score}/100 (not an ATS score)`,r.summary,...r.metrics.map(m=>`${m.name}: ${m.score}/100\n${m.detail}`),'STRENGTHS',...r.strengths,'IMPROVEMENTS',...r.improvements.map(x=>`${x.priority}: ${x.title}\n${x.detail}`),...(r.match?['JOB ALIGNMENT',r.match.summary,'Found: '+r.match.matched.join(', '),'Not evidenced: '+r.match.missing.join(', '),...r.match.requirements.map(x=>`${x.text}\n${x.status}: ${x.evidence}`)]:[]),'SUGGESTED EDITS',...r.rewrites.map(x=>`${x.before}\n→ ${x.after}\n${x.note}`)].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='nextwork-resume-review.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

async function checkResumeBackend(){
const status=$('#backend-status');if(!status)return;
const base=resumeAPIBase();
try{
const response=await fetch(base+'/api/resume',{signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error('Backend unavailable');const state=await response.json();if(state.service!=='prooflane-resume')throw Error('Wrong backend');
status.textContent=state.aiConfigured?'Free-tier AI is available within its quota. Free on-device review is always available.':'Free on-device review is ready. Optional free-tier AI is not configured.';
// Keep free on-device review as the default; remote AI always requires an explicit choice.
}catch{status.textContent='AI server could not be reached. Local review is ready.'}
}

function getResumeListing(id=workspaceSession.getItem('proof-selected-listing')){return jobs.find(j=>j.id===Number(id))}
function listingDescription(j){return `${j.title}\nCompany: ${j.c} (${j.sector})\nEngagement: Paid fixed-scope contract project. Remote. Budget: $${j.pay}. Duration: ${j.weeks}.\nProject brief: ${j.desc}\nSkills requested: ${j.tags.join(', ')}.\nDeliverables: ${j.deliver}\nExpected impact: ${j.impact}${j.demoCreator?'\nProject context: '+j.demoCreator.context+'\nResponsibilities:\n'+j.demoCreator.responsibilities.map(t=>'- '+t).join('\n')+'\nDetailed handoff:\n'+j.demoCreator.deliverables.map(t=>'- '+t).join('\n')+'\nCollaboration: '+j.demoCreator.collaboration+'\nRelevant experience: '+j.demoCreator.fit:''}`}
function listingSummary(id=workspaceSession.getItem('proof-selected-listing'),result=false){const j=getResumeListing(id);if(!j)return '';return `<div class="selected-opportunity"><span class="tag">Sample marketplace listing</span><h3>${esc(j.title)}</h3><p>${esc(j.c)} · $${j.pay.toLocaleString()} · ${esc(j.weeks)} · Remote</p><p>Match feedback uses the skills, brief, and deliverables published on this listing.</p><a href="#project/${j.id}" class="text-link">${result?'View project & apply':'View full project'} ↗</a>${result?`<button class="outline" style="margin-top:14px" onclick="apply(${j.id})">Apply to this project ↗</button>`:''}</div>`}
function saveResumeDraft(){if($('#review-resume'))workspaceSession.setItem('proof-resume',$('#review-resume').value);if($('#review-job'))workspaceSession.setItem('proof-job',$('#review-job').value);if($('#review-job-title'))workspaceSession.setItem('proof-job-title',$('#review-job-title').value)}
function selectResumeListing(id){saveResumeDraft();const j=getResumeListing(id);resumeReport=null;if(j){workspaceSession.setItem('proof-selected-listing',j.id);workspaceSession.setItem('proof-job',listingDescription(j));workspaceSession.setItem('proof-job-title',j.title)}else{workspaceSession.removeItem('proof-selected-listing');workspaceSession.setItem('proof-job','');workspaceSession.setItem('proof-job-title','')}render()}
function matchListing(id){const j=getResumeListing(id);if(!j)return;if(location.hash==='#resume')saveResumeDraft();workspaceSession.setItem('proof-selected-listing',j.id);workspaceSession.setItem('proof-job',listingDescription(j));workspaceSession.setItem('proof-job-title',j.title);resumeMode='job';resumeReport=null;if(location.hash==='#resume')render();else location.hash='resume'}

function setMarketplaceResume(text){const previous=workspaceSession.getItem('proof-resume')||'';workspaceSession.setItem('proof-resume',text);if(previous!==text){sort='match';workspaceLocal.removeItem('proof-resume-report');}}

function resumeAPIBase(){return location.hostname==='nextwork-jobs.vercel.app'?'':'https://nextwork-jobs.vercel.app'}

async function cleanupResumeUploads(){
const owner=Account.user?.id;if(!owner)return;
// Include interrupted uploads as well as the current saved file.
for(;;){const result=await Account.client.storage.from('account-resumes').list(owner,{limit:100});if(result.error)throw result.error;const paths=result.data.filter(row=>row.id).map(row=>owner+'/'+row.name);if(!paths.length)return;const removed=await Account.client.storage.from('account-resumes').remove(paths);if(removed.error)throw removed.error;}
}
